 function open(section=null,id=''){if(!app.state.fileData){app.toast('Önce bir proje açın.');return;}section=visibleTabs[section]?section:null;if(screen&&!section&&!id){root.ASMachRibbon?.select('format');return;}if(screen){void (async()=>{if(!await leave())return;tab=section||tab;selected=id;dirty=false;draft=null;editorMode=id&&spec[tab]?'edit':'';render();root.ASMachRibbon?.select('format');})();return;}tab=section||'project';selected=id;dirty=false;draft=null;editorMode=id&&spec[tab]?'edit':'';const source=app.state.fileData;screen=document.createElement('dialog');screen.id='productionWorkspace';screen.className='project-info-window';screen.setAttribute('aria-label','Proje bilgileri');screen.innerHTML=`<header><div><h2>Proje bilgileri</h2><small>Kimlik, FAI ve üretim kayıtları</small></div><button class="btn" data-close aria-label="Kapat">×</button></header><nav role="tablist" aria-label="Proje bilgi bölümleri"><span class="pr-nav-caption">PROJE</span>${Object.entries(visibleTabs).map(([k,v])=>`<button role="tab" data-tab="${k}">${v}</button>`).join('')}</nav><main></main><footer><span data-status role="status" aria-live="polite"></span><span style="flex:1"></span><small>Bilgiler açık projeye işlenir. Dosyaya yazmak için Dosya > Kaydet komutunu kullanın.</small></footer>`;document.body.append(screen);screen.showModal();screen.addEventListener('cancel',e=>{e.preventDefault();close();});screen.addEventListener('keydown',e=>{e.stopPropagation();if(e.key==='Escape'){e.preventDefault();close();}});
  screen.querySelectorAll('[data-tab]').forEach(b=>b.onclick=async()=>{if(await leave()){tab=b.dataset.tab;selected='';draft=null;dirty=false;render();}});screen.querySelector('[data-close]').onclick=()=>close();render();
  screen.addEventListener('focusin',()=>{if(app.state.fileData!==source){dirty=false;close(true);}});
 }
 async function close(force=false){if(!screen||!force&&!await leave())return;screen.remove();screen=null;dirty=false;draft=null;app.renderAll();}
 root.ASMachProduction={init,open,close,data,links,label,operationLabel,description,form2,materialValues,references,validateRecord,readiness,reportRecords,tableModel};
